/*!
 * wega-music-lap3.js - Lap 3 add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "lap3" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("lap3") works.
 * Track: "Pillar John's Revenge" (Pizza Tower Lap 3, fanmade OST) - supplied by the player.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-lap3] load wega-music.js first"); return; }
  D.lap3 = {
    title: "PILLAR JOHN'S REVENGE (Lap 3 Theme)",
    credit: "Pizza Tower - Pillar John's Revenge (Lap 3, fanmade OST)",
    duration: 244.976,
    loopStart: 0.13,
    loopEnd: 242.9,
    gain: 0.53,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("lap3") < 0) W.tracks.push("lap3");
})(typeof window !== "undefined" ? window : globalThis);
